def procurar(titulos, alvo):
    for indice, titulo in enumerate(titulos):
        if titulo == alvo:
            return indice
    return -1

def classificar(nota):
    if nota >= 7:
        return 'aprovado'
    return 'revisar'

def dobro_texto(texto):
    quantidade = int(texto)
    return quantidade * 2

def situacao(nota):
    if nota < 0 or nota > 10:
        return 'inválida'
    if nota >= 7:
