def contar_multiplos_3(inicio, fim):
    quantidade = 0
    for numero in range(inicio, fim + 1):
        if numero % 3 == 0:
            quantidade += 1
    return quantidade

def iniciais(nome):
    palavras = nome.split()
    return ''.join(palavra[0].upper() for palavra in palavras)

def maior(valores):
    if not valores:
        return None
    return max(valores)

def contar_palavras(palavras):
    contagens = {}
    for palavra in palavras:
        chave = palavra.casefold()
        contagens[chave] = contagens.get(chave, 0) + 1
    return contagens

def frete(total, distancia):
    if total >= 100:
        return 0
    if distancia <= 20:
        return 10
    return 20

def fatorial(n):
    if n < 0:
        raise ValueError('n negativo')
    if n == 0:
        return 1
    return n * fatorial(n - 1)

