solution:
class DescontoFixo:
    def __init__(self, valor):
        self.valor = valor
    def aplicar(self, preco):
        return preco - self.valor

class DescontoPercentual:
    def __init__(self, taxa):
        self.taxa = taxa
    def aplicar(self, preco):
        return preco * (1 - self.taxa)

