solution:
def aviso(tarefas):
    if not tarefas:
        return 'lista vazia'
    return f'{len(tarefas)} tarefa(s)'

def somar_vetores(a, b):
    if len(a) != len(b):
        raise ValueError('tamanhos diferentes')
    return [x + y for x, y in zip(a, b)]

def totais_por_produto(vendas):
    totais = {}
    for venda in vendas:
        produto = venda['produto']
        totais[produto] = totais.get(produto, 0) + venda['valor']
    return totais

def preco_final(preco, taxa):
    if preco < 0 or taxa < 0:
        raise ValueError('entrada negativa')
    return preco * (1 + taxa)

def acuracia(reais, previstos):
    if len(reais) != len(previstos):
        raise ValueError('tamanhos diferentes')
    if not reais:
        return None
    acertos = sum(a == b for a, b in zip(reais, previstos))
    return acertos / len(reais)

def confusao(reais, previstos):
    if len(reais) != len(previstos):
        raise ValueError('tamanhos diferentes')
    vp = fp = vn = fn = 0
    for real, previsto in zip(reais, previstos):
        if real == 1 and previsto == 1: vp += 1
        elif real == 0 and previsto == 1: fp += 1
        elif real == 0 and previsto == 0: vn += 1
        else: fn += 1
    return vp, fp, vn, fn

def buscar_tarefa(tarefas, identificador):
    for tarefa in tarefas:
        if tarefa['id'] == identificador:
            return tarefa
    return None

def resumo_operacao(tarefas):
    return {'concluidas': sum(t.get('status') == 'feito' for t in tarefas),
            'pendentes': sum(t.get('status') == 'pendente' for t in tarefas)}

def total_despesas(valores):
    if any(valor < 0 for valor in valores):
        raise ValueError('despesa negativa')
    return sum(valores)
